DROP TABLE IF EXISTS T CASCADE;
CREATE TABLE T(rid SERIAL, c0 INTEGER NOT NULL,c1 INTEGER NOT NULL,c2 INTEGER,c3 INTEGER,c4 INTEGER,c5 INTEGER,c6 INTEGER,c7 INTEGER);
CREATE UNIQUE INDEX k0_0 ON T(c2,c3) WHERE c2 IS NOT NULL AND c3 IS NOT NULL;
CREATE UNIQUE INDEX k0_1 ON T(c3) WHERE c2 IS NULL AND c3 IS NOT NULL;
CREATE UNIQUE INDEX k0_2 ON T(c2) WHERE c3 IS NULL AND c2 IS NOT NULL;
CREATE UNIQUE INDEX k0_3 ON T((1)) WHERE c2 IS NULL AND c3 IS NULL;
CREATE OR REPLACE FUNCTION chk_k0() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
  IF (NEW.c2 IS NOT NULL AND NEW.c3 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c2=NEW.c2 AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  IF (NEW.c2 IS NULL AND NEW.c3 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL AND c3=NEW.c3) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  IF (NEW.c3 IS NULL AND NEW.c2 IS NOT NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL AND c2=NEW.c2) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  IF (NEW.c2 IS NULL AND NEW.c3 IS NULL) AND (EXISTS (SELECT 1 FROM T WHERE (c2 IS NOT NULL AND c3 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c3 IS NULL AND c2 IS NOT NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid)) OR EXISTS (SELECT 1 FROM T WHERE (c2 IS NULL AND c3 IS NULL) AND (TG_OP = 'INSERT' OR ctid <> OLD.ctid))) THEN RAISE EXCEPTION 'certain key k0 violated'; END IF;
  RETURN NEW; END $$;
CREATE TRIGGER trg_k0 BEFORE INSERT OR UPDATE ON T FOR EACH ROW EXECUTE FUNCTION chk_k0();
